=<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <style>
        body { font-family: 'Segoe UI', Helvetica, Arial, sans-serif; background-color: #f4f7fa; color: #1e293b; margin: 0; padding: 0; }
        .wrapper { background-color: #f4f7fa; padding: 30px 10px; }
        .container { max-width: 600px; margin: 0 auto; background: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 10px 40px rgba(0,0,0,0.15); border: 1px solid #e2e8f0; }
        .header { background: #1a0a2e; padding: 40px 20px 30px; text-align: center; }
        /* Logo masivo y centrado sin espacios muertos */
        .logo-container {
            width: 320px;
            height: 100px;
            margin: 0 auto;
            background-image: url('https://sofia-solutions.serveousercontent.com/assets/logo-soc-final.png');
            background-size: contain;
            background-repeat: no-repeat;
            background-position: center bottom;
        }
        .slogan { font-size: 12px; color: #a78bfa; letter-spacing: 4px; margin-top: 15px; text-transform: uppercase; font-weight: 700; }
        .content { padding: 40px 35px; }
        .badge { display: inline-block; padding: 6px 14px; border-radius: 6px; font-weight: 800; font-size: 11px; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 25px; }
        .badge-critical { background: #fee2e2; color: #ef4444; border: 1px solid #fca5a5; }
        .badge-high { background: #fef3c7; color: #f59e0b; border: 1px solid #fcd34d; }
        .title { font-size: 28px; font-weight: 800; color: #0f172a; margin: 0 0 15px; letter-spacing: -0.5px; }
        .alert-box { background: #f8fafc; border-radius: 10px; padding: 25px; margin-bottom: 35px; border: 1px solid #e2e8f0; border-left: 6px solid #8b5cf6; }
        .description { font-size: 16px; color: #475569; line-height: 1.6; margin: 0; }
        .tech-table { width: 100%; border-collapse: collapse; margin-bottom: 35px; }
        .tech-row { border-bottom: 1px solid #f1f5f9; }
        .tech-label { padding: 15px 0; color: #64748b; font-size: 11px; font-weight: 700; text-transform: uppercase; width: 120px; }
        .tech-value { padding: 15px 0; color: #1e293b; font-size: 15px; font-weight: 600; }
        .btn { display: inline-block; background: #1a0a2e; color: #ffffff !important; text-decoration: none; padding: 20px 45px; border-radius: 8px; font-weight: 700; font-size: 15px; text-transform: uppercase; letter-spacing: 1px; }

        @media only screen and (max-width: 600px) {
            .logo-container { width: 260px; height: 80px; }
            .header { padding: 30px 15px 20px; }
            .content { padding: 30px 20px; }
            .btn { width: 100%; text-align: center; box-sizing: border-box; }
        }
    </style>
</head>
<body>
    <div class="wrapper">
        <div class="container">
            <div class="header">
                <div class="logo-container" aria-label="Sofia Solutions"></div>
                <div class="slogan">Tu Seguridad, Nuestra Misión</div>
            </div>
            <div class="content">
                <div class="badge badge-{{ ($json.body?.severity || $json.severity || 'urgent').toLowerCase() === 'high' ? 'high' : 'critical' }}">
                    {{ {high:'ALTA', critical:'CRÍTICA', urgent:'URGENTE'}[($json.body?.severity || $json.severity || 'urgent').toLowerCase()] || 'ALTA' }}
                </div>
                <h2 class="title">Alerta de Seguridad SOC</h2>
                <div class="alert-box">
                    <p class="description">{{ ($json.body?.description || $json.description || 'Se ha detectado un evento de seguridad crítico que requiere atención inmediata.').replace(/\\u([0-9a-fA-F]{4})/g, (m,g)=>String.fromCharCode(parseInt(g,16))) }}</p>
                </div>

                <table class="tech-table">
                    <tr class="tech-row">
                        <td class="tech-label">Incidente</td>
                        <td class="tech-value">{{ ($json.body?.title || $json.title || 'Alerta de Seguridad').replace(/\\u([0-9a-fA-F]{4})/g, (m,g)=>String.fromCharCode(parseInt(g,16))) }}</td>
                    </tr>
                    <tr class="tech-row">
                        <td class="tech-label">ID Evento</td>
                        <td class="tech-value">#SOC-{{ $json.body?.alertId || $json.alertId || '5120' }}</td>
                    </tr>
                    <tr class="tech-row">
                        <td class="tech-label">Monitorización</td>
                        <td class="tech-value">Sofia AI Sentinel v4.0</td>
                    </tr>
                    <tr class="tech-row">
                        <td class="tech-label">Timestamp</td>
                        <td class="tech-value">{{ $json.body?.timestamp || $json.timestamp || '2026-05-06 22:52' }}</td>
                    </tr>
                </table>

                <div style="text-align: center;">
                    <a href="https://sofia-n8n.serveousercontent.com" class="btn">ACCEDER AL PANEL SOC</a>
                </div>
            </div>
            <div class="footer">
                CENTRO DE SEGURIDAD SOFIA SOLUTIONS (SOC) 24/7<br>
                &copy; 2026 Sofia Solutions Security Group.
            </div>
        </div>
    </div>
</body>
</html>
